mapper.select:
select * from ( select rownum rnum,a.* from( select c.coach_idx, u.user_idx, u.user_name, c.nickname, c.phone, u.created_at, u.status, (select count(*) from cert c_sub where c_sub.user_idx = c.user_idx and cert_status = '대기') as cert_wait_count from coach c join users u on c.user_idx = u.user_idx
AND ( c.coach_idx LIKE '%' || #{keyword} || '%' OR u.user_name LIKE '%' || #{keyword} || '%' OR c.nickname LIKE '%' || #{keyword} || '%' )
order by cert_wait_count desc, c.coach_idx desc
order by c.coach_idx desc
)a )where rnum between #{start} and #{end}

mapper.update:
update cert 
set cert_name=#{cert_name, jdbcType=VARCHAR}, 
get_date = #{get_date, jdbcType=DATE}, 
cert_from=#{cert_from, jdbcType=VARCHAR}, 
cert_status=#{cert_status, jdbcType=VARCHAR}
where cert_idx=#{cert_idx}

mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY m.MATCH_IDX DESC) AS rnum, m.MATCH_IDX, u1.USER_NAME AS SENDER, u2.USER_NAME AS RECEIVER, CASE WHEN s.SCHEDULE_IDX IS NOT NULL THEN '일정확정' WHEN a.AGREEMENT_IDX IS NOT NULL THEN '서약완료' WHEN m.IS_MATCH = 'Y' THEN '매칭완료' WHEN m.IS_CHAT = 'Y' THEN '채팅중' ELSE '대기' END AS PROGRESS_STATUS, NVL(s.START_DATE, a.CREATED_AT) AS LAST_ACTION_DATE FROM MATCH m JOIN USERS u1 ON m.USER1_IDX = u1.USER_IDX JOIN USERS u2 ON m.USER2_IDX = u2.USER_IDX LEFT JOIN AGREEMENT a ON ( (m.USER1_IDX = a.WRITER_IDX AND m.USER2_IDX = a.RECEIVER_IDX) OR (m.USER1_IDX = a.RECEIVER_IDX AND m.USER2_IDX = a.WRITER_IDX) ) LEFT JOIN SCHEDULE s ON a.AGREEMENT_IDX = s.AGREEMENT_IDX
(u1.USER_NAME LIKE '%' || #{keyword} || '%' OR u2.USER_NAME LIKE '%' || #{keyword} || '%')
) WHERE rnum BETWEEN #{start} AND #{end}

select keyword_name 
from keyword 


	keyword_type=#{keyword_type}

select r.review_idx, r.reviewer_idx, max(u.user_name) as user_name, r.role, max(r.content)as content, max(r.created_at) as created_at, listagg(k.keyword_name,',') within group (order by k.keyword_name) as keywords from ( select review_coach_idx as review_idx,reviewer_idx,content,created_at,'COACH' as role from review_coach union all select review_class_idx as review_idx,reviewer_idx,content,created_at,'CLASS' as role from review_class ) r join users u on r.reviewer_idx = u.user_idx join ( select keyword_type,keyword_name from keyword
keyword_type=#{keyword_type}
) k on r.content like '%' || k.keyword_name || '%' group by r.review_idx,r.reviewer_idx,r.role order by created_at desc

select * from( select rownum rnum,a.* from( select r.report_idx, rt.content, u1.user_name as reporter_name, u2.user_name as reported_name, r.status, r.created_at from report r join users u1 on r.reporter_idx=u1.user_idx join users u2 on r.reported_idx=u2.user_idx join reason_type rt on r.reason_type_idx=rt.reason_type_idx
and r.status=#{status}
order by r.report_idx desc )a )where rnum between #{start} and #{end}
